import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        if (n == 0) {
            System.out.println(k == 0 ? 0 : -1);
            return;
        }
        if (k < 1 || k > n) {
            System.out.println(-1);
            return;
        }
        final long INF = Long.MAX_VALUE / 4;
        // previous[end]: best cost of a[0..end) split into (groups-1) segments
        long[] previous = new long[n + 1], current = new long[n + 1];
        Arrays.fill(previous, INF);
        previous[0] = 0;
        for (int groups = 1; groups <= k; groups++) {
            Arrays.fill(current, INF);
            for (int end = groups; end <= n; end++) {
                long largest = 0, best = INF;
                for (int start = end - 1; start >= groups - 1; start--) {
                    largest = Math.max(largest, a[start]); // maximum of the last segment a[start..end)
                    best = Math.min(best, previous[start] + largest);
                }
                current[end] = best;
            }
            long[] t = previous; previous = current; current = t;
        }
        System.out.println(previous[n]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	if n == 0 {
		if k == 0 {
			fmt.Println(0)
		} else {
			fmt.Println(-1)
		}
		return
	}
	if k < 1 || k > n {
		fmt.Println(-1)
		return
	}
	const INF = int64(1) << 60
	// previous[end]: best cost of a[0:end] split into (groups-1) segments
	previous := make([]int64, n+1)
	current := make([]int64, n+1)
	for i := range previous {
		previous[i] = INF
	}
	previous[0] = 0
	for groups := 1; groups <= k; groups++ {
		for i := range current {
			current[i] = INF
		}
		for end := groups; end <= n; end++ {
			largest, best := int64(0), INF
			for start := end - 1; start >= groups-1; start-- {
				largest = max(largest, a[start]) // maximum of the last segment a[start:end]
				best = min(best, previous[start]+largest)
			}
			current[end] = best
		}
		previous, current = current, previous
	}
	fmt.Println(previous[n])
}
